"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["7053"],{5003(e,t,i){i.r(t),i.d(t,{metadata:()=>n,default:()=>h,frontMatter:()=>a,contentTitle:()=>s,toc:()=>d,assets:()=>c});var n=JSON.parse('{"id":"reference/monitor/howtos/deleteSystemOrGateway","title":"Deleting Systems in ALMS","description":"almsc \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/monitor/howtos/deleteSystemOrGateway.md","sourceDirName":"reference/monitor/howtos","slug":"/reference/monitor/howtos/deleteSystemOrGateway","permalink":"/personal-av-docs/docs/reference/monitor/howtos/deleteSystemOrGateway","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/monitor/howtos/deleteSystemOrGateway.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"Deleting Systems in ALMS","sidebar_label":"Deleting Systems in ALMS","sidebar_position":99,"edition":"almsc","source":"https://doc.airvantage.net/almsc/reference/monitor/howtos/deleteSystemOrGateway","format":"md"}}'),r=i(4848),o=i(8453);let a={title:"Deleting Systems in ALMS",sidebar_label:"Deleting Systems in ALMS",sidebar_position:99,edition:"almsc",source:"https://doc.airvantage.net/almsc/reference/monitor/howtos/deleteSystemOrGateway",format:"md"},s,c={},d=[];function l(e){let t={a:"a",p:"p",strong:"strong",...(0,o.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsxs)(t.p,{children:[":::note Edition\n",(0,r.jsx)(t.strong,{children:"almsc"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,r.jsx)(t.a,{href:"https://doc.airvantage.net/almsc/reference/monitor/howtos/deleteSystemOrGateway",children:"Original page"}),".\n:::"]}),"\n",(0,r.jsx)(t.p,{children:"Deleting Systems in ALMS\nWith AirLink Complete, the first year of service is included as part of the purchase of an AirLink router. When registered and activated, the initial term of service for the router in ALMS is set to one year. You cannot directly delete the device during this period (referred to as the \u201CEngagement Period\u201D).\nIf you try and delete a device from ALMS during its engagement period, the following warning appears:\nSierra Wireless recommends that customers leave their devices registered in their ALMS account for as long as the devices are active. There are a clear benefits to doing so:\nIt ensures that the device is registered to you, as its\u2019 owner and prevents unauthorized third parties from claiming your devices.\nALMS is the system of record for Support and Warranty information. When your device is registered in ALMS, you will see the dates of your service entitlement and receive notifications for renewals.\nYou are better prepared to manage your devices with easy access to firmware upgrades when they are released.\nWe understand that there may be situations where deleting a device from ALMS may be required. The behavior of the system will depend on the state of the device:\nWithin the Engagement Period\nIf your device is within the first year of service, deleting it is a two-step process. First you must terminate the Service, and then delete the system.\nTerminate the Service.\nOn the Monitor > Systems page, select the drop-down arrow from the Service Action Buttons.\nSelect\nTerminate\n.\nConfirm the Terminate action.\nThe Terminate warning screen appears.\nFor most device types you can click\nTerminate\nwithout concern. This applies to any devices that are activated on standard offers that only use device management services in ALMS, such as AirLink Basic or AirLink Complete (but not AirLink Complete (XR80) or AirLink Premium).\nFor AirLink XR80 and XR90 routers, DO NOT click\nTerminate\nunless you are not planning to use these devices in the future, and do plan to physically retire them. Please see the note below.\nFor any device that has activated Connectivity as part of their offer, DO NOT click\nTerminate\nunless you are not planning to use these devices in the future as you will terminate your SIM.\nYou will see an Operation in ALMS confirming the Terminate action.\nDelete the system from ALMS.\nClick the drop-down link on the first set of action buttons.\nSelect\nDelete\n.\nOutside the Engagement Period\nIf your device is outside its engagement period, you can delete it at any time. For customers with AirLink XR80 and XR90 devices, please review the note below.\nRe-registration of Devices\nTo activate a new device on its included support plan, customers are expected to register their devices within 60 days of purchase. Devices that are deleted and re-registered will, by default, have the original services re-applied to their devices. If a device is outside its eligibility window, the device may be registered into the account in an inactive (suspended) state. If the device is suspended, please contact Sierra Wireless Customer Support to reactivate it. You may need to purchase service for the device.\nNotice for AirLink XR80 and XR90 Customers\nThe AirLink XR80 and XR90 routers include a special out-of-band management (OOBM) radio. This radio is separate from the primary cellular radio(s) in your XR80/90 routers, and as a result, these devices must be treated differently in ALMS as it relates to managing their services and deleting devices.\nThe services for this class of device (AirLink Complete for the XR80, AirLink Premium for the XR90) include the OOBM link and the connectivity services to support it, provided that your devices are active on an appropriate service plan. When you first register and activate the router you also activate the SIM in the OOBM radio, allowing it to send the device management traffic to ALMS, even if your primary radio(s) are inactive.\nBecause of this additional radio, it is critical that devices not be Terminated or Deleted from ALMS, for risk of terminating the SIM card in the XR80/90s. Only Terminate and Delete an XR80 or XR90 if you intend never to use it again. Once terminated, the SIM in the OOBM radio cannot be recovered or reactivated.\nThis is a permanent outcome.\nRather than deleting, this class of device should be transferred from one account to another. This approach is used, for example, when processing an RMA on a device that has an issue. For clarification on this topic, please contact Sierra Wireless Customer Support."})]})}function h(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(l,{...e})}):l(e)}},8453(e,t,i){i.d(t,{R:()=>a,x:()=>s});var n=i(6540);let r={},o=n.createContext(r);function a(e){let t=n.useContext(o);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:a(e.components),n.createElement(o.Provider,{value:t},e.children)}}}]);